package ai.decisionos.aside;
import org.json.*;import java.time.*;import java.util.regex.*;
/** Extract only explicit source dates. Posting dates and historical examples never become deadlines. */
final class CampusSignal {
 static final String[][] TOPICS={{"장학","장학|scholarship"},{"학점교류","학점.?교류|계절학기"},{"시험","시험|기말|exam|open.?book|오픈북|채점"},{"과제","과제|assignment|due"},{"학적","휴학|복학|전공.?변경|졸업|박사|정원|수강"},{"인턴십","인턴|현장실습|internship|COOP|몰입캠프"},{"행사","간식|햄버거|축제|창의축전|세미나|강연"},{"시설","사용.?불가|이용.?제한|폐쇄"},{"팀활동","팀플|팀.?프로젝트|팀.?활동"},{"메시지","messages?|메시지"},{"공모전","공모전|대회|지원사업"}};
 static JSONObject extract(String title,String text,String url,String posted,long now){JSONObject out=new JSONObject();String body=(title+"\n"+text).substring(0,Math.min(30000,(title+"\n"+text).length()));JSONArray tags=new JSONArray(),deadlines=new JSONArray(),amounts=new JSONArray();for(String[] t:TOPICS)if(Pattern.compile(t[1],Pattern.CASE_INSENSITIVE).matcher(body).find())tags.put(t[0]);
 // A date must appear on a deadline-labelled line, with an explicit year. Do not infer from posting year.
 Pattern date=Pattern.compile("(?<![0-9])((?:20)[0-9]{2})[.년/\\-]\\s*([0-9]{1,2})[.월/\\-]\\s*([0-9]{1,2})(?:일)?(?![0-9])");java.util.Set<String> seen=new java.util.HashSet<>();for(String line:body.split("\\n")){if(!line.matches("(?i).*(마감|까지|기한|deadline|due|시험일|시험.?일정).*"))continue;if(line.matches(".*(작년|전년도|예시|지난해|예상).*"))continue;Matcher m=date.matcher(line);while(m.find())try{String day=LocalDate.of(Integer.parseInt(m.group(1)),Integer.parseInt(m.group(2)),Integer.parseInt(m.group(3))).toString();if(seen.add(day)){JSONObject d=new JSONObject();GoalStore.put(d,"date",day);GoalStore.put(d,"basis",line.substring(0,Math.min(300,line.length())));GoalStore.put(d,"time_verified",false);GoalStore.put(d,"expired",LocalDate.parse(day).isBefore(Instant.ofEpochMilli(now).atZone(ZoneId.of("Asia/Seoul")).toLocalDate()));deadlines.put(d);}}catch(Exception ignored){}}
 Matcher amount=Pattern.compile("[0-9][0-9,]*(?:\\.[0-9]+)?\\s*(?:만\\s*)?원").matcher(body);while(amount.find()&&amounts.length()<10)amounts.put(amount.group());GoalStore.put(out,"categories",tags);GoalStore.put(out,"deadlines",deadlines);GoalStore.put(out,"amount_mentions",amounts);GoalStore.put(out,"source_url",url);GoalStore.put(out,"posted",posted);GoalStore.put(out,"observed_at",now);GoalStore.put(out,"deadline_status",deadlines.length()>0?"explicit_source_date":"unknown");GoalStore.put(out,"eligibility","원문과 사용자 학적·자격 확인 필요");return out;}
}
